/** AG monogram only — nav, buttons, small spaces. */
export function Monogram({
  className,
  tone = "ink",
}: {
  className?: string;
  tone?: "ink" | "light" | "champagne";
}) {
  const color =
    tone === "light"
      ? "text-alabaster"
      : tone === "champagne"
        ? "text-champagne"
        : "text-ink";

  return (
    <svg
      viewBox={MONO_VIEWBOX}
      className={cn("h-6 w-auto", color, className)}
      fill="currentColor"
      fillRule="evenodd"
      aria-hidden="true"
      focusable="false"
    >
      <path d={MONO_PATH} />
    </svg>
  );
}

/** Full AG + ANLOSSA lockup — footer plate, mobile menu. */
export function LogoLockup({
  className,
  tone = "ink",
}: {
  className?: string;
  tone?: "ink" | "light";
}) {
  return (
    <svg
      viewBox={LOCKUP_VIEWBOX}
      className={cn(
        "w-40",
        tone === "light" ? "text-alabaster" : "text-ink",
        className
      )}
      fill="currentColor"
      fillRule="evenodd"
      role="img"
      aria-label="Anlossa Services"
    >
      <path d={LOCKUP_PATH} />
    </svg>
  );
}
